"""Read-only D6/D7 boundary comparison on the frozen Semantica owner sources."""

import contextlib
import io
import json
import os
import subprocess
import sys
import tempfile
from pathlib import Path

with contextlib.redirect_stdout(io.StringIO()):
    from apps.api.api.routes.search import _project_current_search_symbols as api_project
    from apps.mcp.mcp.adapters.search.query_adapter import QueryAdapter
    from apps.mcp.mcp.domain import query_surface_registry as registry
    from apps.mcp.mcp.handlers import introspection


def symbol_result(symbol, **extra):
    return {"symbols": [symbol], "total": 1, "truncated": False, **extra}


symbol = {
    "symbol_id": "sid",
    "name": "fun",
    "kind": "function",
    "location": {
        "file_path": "x.py",
        "start_line": 1,
        "start_column": 0,
        "end_line": 1,
        "end_column": 2,
    },
    "score": 0.5,
}


def project(fn, payload):
    try:
        value = fn(payload)
        return {"ok": True, "repr": repr(value)}
    except Exception as exc:
        return {"ok": False, "error": type(exc).__name__, "reason": str(exc)}


cases = {
    "canonical": symbol_result(symbol),
    "extra_envelope": symbol_result(symbol, status="degraded"),
    "bad_total": {**symbol_result(symbol), "total": 0},
    "bad_truncated": {**symbol_result(symbol), "truncated": "false"},
    "legacy_hits": {"hits": [{"id": "a", "file_path": "x.py", "score": 0.3}]},
    "bool_line": symbol_result({**symbol, "location": {**symbol["location"], "start_line": True}}),
    "nan_score": symbol_result({**symbol, "score": float("nan")}),
    "extra_symbol": symbol_result({**symbol, "search_surface": "text"}),
}

result = {
    "projection_cases": {
        name: {
            "api": project(api_project, payload),
            "agent": project(QueryAdapter._extract_search_hits_v1, payload),
        }
        for name, payload in cases.items()
    }
}

with tempfile.TemporaryDirectory() as directory:
    project_manifest = Path(directory) / ".ai/generated/crosswalk.json"
    project_manifest.parent.mkdir(parents=True)
    project_manifest.write_text('{"version":"1","entries":[]}', encoding="utf-8")
    os.environ["CODEGRAPH_REPO_PATH"] = directory
    paths = {}
    for case_name, explicit in (
        ("project_only", None),
        ("bad_override", str(Path(directory) / "missing.json")),
        ("valid_override", str(project_manifest)),
    ):
        if explicit is None:
            os.environ.pop("CODEGRAPH_CROSSWALK_PATH", None)
        else:
            os.environ["CODEGRAPH_CROSSWALK_PATH"] = explicit
        registry._canonical_crosswalk_path_v1.cache_clear()
        paths[case_name] = {
            "introspection": str(introspection._find_crosswalk_path()),
            "registry": str(registry._canonical_crosswalk_path_v1()),
        }
    result["resolver_cases"] = paths

launcher = (
    "from apps.mcp.mcp.main import _build_tool_list\n"
    "try:\n"
    " print('NAMES', [tool.name for tool in _build_tool_list()])\n"
    "except Exception as exc:\n"
    " print('ERROR', type(exc).__name__, str(exc))\n"
)
canonical = registry._DEFAULT_CANONICAL_CROSSWALK_PATH
startup = {}
for case_name, explicit in (("no_override", None), ("canonical_override", str(canonical))):
    env = os.environ.copy()
    env.pop("CODEGRAPH_REPO_PATH", None)
    if explicit is None:
        env.pop("CODEGRAPH_CROSSWALK_PATH", None)
    else:
        env["CODEGRAPH_CROSSWALK_PATH"] = explicit
    process = subprocess.run(
        [sys.executable, "-c", launcher], capture_output=True, text=True, env=env, check=False
    )
    startup[case_name] = {
        "exit_code": process.returncode,
        "stdout": process.stdout,
        "stderr": process.stderr,
    }
result["startup_cases"] = startup

print(json.dumps(result, sort_keys=True, indent=2, allow_nan=False))

