import hashlib
import json
from codegraph_sdk._generated_daemon_contract_v1 import ProductResponseV1
from codegraph_sdk._product_search_projection_v1 import project_registered_query_search_product_response_v1
from codegraph_sdk._product_apply_changes_projection_v1 import project_apply_changes_product_response_v1
from codegraph_sdk.client import SdkClient, _RESPONSE_SHAPE_OPERATION_ROW_MAP_V1
from codegraph_sdk.exceptions import SdkError
from apps.api.api.routes.indexing import _coerce_apply_changes_response_v1


def scalar(value, kind):
    return {"scalar": kind, "value": value}


def field(value, kind):
    return {"field": "scalar", "value": scalar(value, kind)}


def envelope(service, operation, kind, rows, summary=None, status="ok", degraded=()):
    value = {
        "request_id": "audit-request-1", "status": status, "failure_class": None,
        "degraded": list(degraded), "not_computed": [],
        "payload": {"kind": kind, "rows": rows, "summary": summary or {}},
        "proof": {"proof": "absent", "reason": "controlled-audit-input"},
        "receipt": None, "committed_mutation_v1": None,
        "metadata": {"snapshot_id": None, "query_plan_id": None, "runtime_revision": "audit",
                     "service": service, "operation_id": operation,
                     "negotiated": {"protocol_version": 3, "capabilities": []}},
    }
    canonical = ProductResponseV1.from_mapping_v1(value).to_mapping_v1()
    return canonical, hashlib.sha256(json.dumps(canonical, sort_keys=True, separators=(',', ':')).encode()).hexdigest()


def outcome(call):
    try:
        return {"type": "return", "value": call()}
    except Exception as error:
        return {"type": "raise", "class": type(error).__name__, "message": str(error)}

native_row = {"fields": {"row_kind": field("match", "text"), "snippet": field("def f():", "text"),
                         "symbol_fqn": field("pkg.f", "text"), "symbol_kind": field("function", "text"),
                         "file_path": field("src/f.py", "text"), "line": field(2, "integer"),
                         "score": field("0.8", "decimal")}}
consumer_row = {"fields": {"symbol_id": field("real-sid", "text"), "name": field("pkg.f", "text"),
                           "kind": field("function", "text"), "file_path": field("src/f.py", "path"),
                           "line": field(2, "integer"), "score": field("0.8", "decimal")}}
search_kind = {"kind": "search_hits"}
search_summary = {"total_count": scalar(3, "integer"), "result_truncated": scalar(True, "boolean")}
search_native, native_hash = envelope("query", "query.search", search_kind, [native_row], search_summary)
search_control, control_hash = envelope("query", "query.search", search_kind, [consumer_row], {"total": scalar(1, "integer"), "truncated": scalar(False, "boolean")})
search_empty, empty_hash = envelope("query", "query.search", search_kind, [], search_summary)
search = {
    "native_row": outcome(lambda: project_registered_query_search_product_response_v1(search_native, method_name="audit.search")),
    "consumer_control": outcome(lambda: project_registered_query_search_product_response_v1(search_control, method_name="audit.search")),
    "empty_summary": outcome(lambda: project_registered_query_search_product_response_v1(search_empty, method_name="audit.search")),
}
assert search["native_row"]["type"] == "raise" and search["native_row"]["class"] == "SdkError"
assert search["consumer_control"]["value"]["data"]["symbols"][0]["symbol_id"] == "real-sid"
assert search["empty_summary"]["value"]["data"]["total"] == 0
assert search["empty_summary"]["value"]["data"]["truncated"] is False

mutation_kind = {"kind": "mutation", "operation": "apply-changes"}
mutation_row = {"fields": {"applied": field(1, "integer"), "deleted": field(0, "integer"),
                           "analysis_invalidation_state": {"field": "rows", "rows": [{"fields": {"recompute_scope": field("affected", "text")}}]},
                           "recompute_execution_state_v1": {"field": "rows", "rows": [{"fields": {"execution_mode": field("failed_closed", "text")}}]},
                           "apply_changes_envelope_contract_v1": {"field": "rows", "rows": [{"fields": {"mutation_committed": field(True, "boolean"), "analysis_recompute_failed_closed": field(True, "boolean")}}]}}}
reason = {"code": "mutation_partial_result", "detail": "analysis recompute failed after mutation commit"}
mutation_wire, mutation_hash = envelope("mutation", "mutation.apply-changes", mutation_kind, [mutation_row], status="degraded", degraded=[reason])
projected = project_apply_changes_product_response_v1(mutation_wire, method_name="audit.mutation", operation_shape_rows=_RESPONSE_SHAPE_OPERATION_ROW_MAP_V1)
client = object.__new__(SdkClient)
public = SdkClient._require_command_result_dict(client, projected, "audit.mutation")
api = _coerce_apply_changes_response_v1(public)
mutation = {"internal_status": projected["outcome_status_v1"], "internal_reason": projected["degraded_reasons"],
            "public_keys": sorted(public), "public_failed_analysis": public["apply_changes_envelope_contract_v1"]["analysis_recompute_failed_closed"],
            "api_ok": api.ok, "api_data_has_status": "outcome_status_v1" in api.data}
assert mutation["internal_status"] == "degraded" and mutation["public_failed_analysis"] is True
assert "outcome_status_v1" not in public and mutation["api_ok"] is True and not mutation["api_data_has_status"]
print(json.dumps({"search": search, "mutation": mutation,
                  "fixture_sha256": {"native_row": native_hash, "consumer_control": control_hash, "empty_summary": empty_hash, "mutation_degraded": mutation_hash}}, sort_keys=True, indent=2))

